def prime_fib(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    a, b = 0, 1
    for _ in range(n):
        if is_prime(b):
            return b
        a, b = b, a + b

prime_fib(1)
```

